using ghidra.util.task;

public class BySectionAutoMapSpec : AutoMapSpec {
	public static readonly string CONFIG_NAME = "1_MAP_BY_SECTION";

	/* @Override */
	public string getConfigName() {
		return CONFIG_NAME;
	}

	/* @Override */
	public string getMenuName() {
		return "Auto-Map by Section";
	}

	/* @Override */
	public Icon getMenuIcon() {
		return DebuggerResources.ICON_CONFIG;
	}

	/* @Override */
	public Collection<TraceEvent<object,object>> getChangeTypes() {
		return List.of(TraceEvents.SECTION_ADDED);
	}

	/* @Override */
	public bool objectHasType(TraceObjectValue value) {
		return value.getParent().queryInterface(typeof(TraceSection)) != null;
	}

	/* @Override */
	public string getInfoForObjects(Trace trace, long snap) {
		return trace.getModuleManager()
				.getAllSections()
				.stream()
				.filter(s => s.isValid(snap))
				.map(s => s.getName(snap) + ":" + s.getStart(snap))
				.sorted()
				.collect(Collectors.joining(","));
	}

	/* @Override */
	public List<Program> programs(ProgramManager programManager) {
		return Arrays.asList(programManager.getAllOpenPrograms());
	}

	/* @Override */
	public bool performMapping(DebuggerStaticMappingService mappingService, Trace trace,
			long snap, List<Program> programs, TaskMonitor monitor)
    {
		Map<object, SectionMapProposal> maps = mappingService.proposeSectionMaps(
			trace.getModuleManager().getLoadedModules(snap), snap, programs);
		Collection<SectionMapEntry> entries = MapProposal.flatten(maps.values());
		entries = MapProposal.removeOverlapping(entries);
		mappingService.addSectionMappings(entries, monitor, false);
		return !entries.isEmpty();
	}
}
